/* eslint-disable */

import AddOrder from "./AddOrder.vue";
import ViewOrder from "./ViewOrder.vue";
import SnackBar from "@/components/SnackBar.vue";
import { API, graphqlOperation } from "aws-amplify";
import { list_orders } from "@/graphql/queries.js";
import CancelOrder from "./CancelOrder.vue";
import DispatchView from "./DispatchView.vue";
export default {
  components: {
    AddOrder,
    ViewOrder,
    SnackBar,
    CancelOrder,
    DispatchView
  },
  data() {
    return {
      SnackBarComponent: {},
      tableLoading: false,
      fixed: true,
      Headers: [{
        title: "Delivery Date",
        key: "expected_delevery_date"
      }, {
        title: "Customer Name",
        key: "customer_name",
        sortable: false
      }, {
        title: "Order ID",
        key: "order_transaction_id",
        sortable: false
      }, {
        title: "Product",
        key: "products_count",
        sortable: false
      }, {
        title: "Advance Paid",
        key: "advance_recevied",
        sortable: false
      }, {
        title: "Balance Amount",
        key: "remaining_amount",
        sortable: false
      }, {
        title: "Delivery Agent",
        key: "delivey_agent",
        sortable: false
      }, {
        title: "Status",
        key: "order_delevery_status",
        sortable: false
      }, {
        title: "Action",
        key: "action",
        sortable: false
      }],
      tableData: [],
      componentCheck: 0,
      addOrderDialog: false,
      ViewOrderDialog: false,
      nextToken: null,
      filterOrder: "ALL",
      cancelOrderDialig: false,
      dispatchOrderDialog: false,
      currentPage: 1,
      itemsPerPage: 20
    };
  },
  computed: {
    totalCount() {
      return this.tableData.length;
    },
    pageCount() {
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    }
  },
  created() {
    this.fetch_Orderlist();
  },
  watch: {
    filterOrder(newVal) {
      this.fetch_Orderlist();
    },
    currentPage() {
      // Scroll to top when page changes
      const table = document.querySelector(".dtwidth");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  methods: {
    add_order() {
      this.addOrderDialog = true;
      this.componentCheck = 1;
    },
    view_order(item) {
      this.ViewOrderDialog = true;
      this.componentCheck = 2;
      this.rowInfo = item;
    },
    cancel_order(item) {
      this.componentCheck = 3;
      this.rowInfo = item;
      this.cancelOrderDialig = true;
    },
    dispatch_order(item) {
      this.componentCheck = 4;
      this.rowInfo = item;
      this.dispatchOrderDialog = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.tableData = [];
      this.addOrderDialog = false;
      this.cancelOrderDialig = false;
      this.dispatchOrderDialog = false;
      this.ViewOrderDialog = false;
      this.fetch_Orderlist();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async fetch_Orderlist() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_orders, {
          input: {
            limit: 100,
            nextToken: this.nextToken,
            order_delevery_status: this.filterOrder
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_orders);
        this.tableLoading = false;
        this.tableData = response.data;
      } catch (error) {
        this.tableLoading = false;
        this.tableData = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    handle_row_click(click, val) {
      // Optionally implement row click if needed
    }
  }
};
